+	/** @internal Relative position of the boundary, used to validate frame ordering. */
+	get position(): number {
+		switch (this.kind) {
+			case 'unbounded preceding': {
+				return Number.NEGATIVE_INFINITY;
+			}
+			case 'preceding': {
+				return -this.offset!;
+			}
+			case 'current row': {
+				return 0;
+			}
+			case 'following': {
+				return this.offset!;
+			}
+			case 'unbounded following': {
+				return Number.POSITIVE_INFINITY;
+			}
+		}
+	}
+
+	/** @internal */
+	toSQL(): SQL {
+		switch (this.kind) {
+			case 'preceding': {
+				return sql.raw(`${this.offset} preceding`);
+			}
+			case 'following': {
+				return sql.raw(`${this.offset} following`);
+			}
+			default: {
+				return sql.raw(this.kind);
+			}
+		}
+	}
